import { fileURLToPath } from 'node:url';
import { migrate } from 'drizzle-orm/node-postgres/migrator';
import type pg from 'pg';
import { createDatabase } from './client.js';

/** SQL migrations generated by drizzle-kit (`apps/api/drizzle`). */
export const MIGRATIONS_FOLDER = fileURLToPath(new URL('../../drizzle', import.meta.url));

/**
 * Applies pending migrations. Already-applied ones are recorded in
 * `drizzle.__drizzle_migrations` and skipped, so running this again is a no-op.
 */
export async function runMigrations(pool: pg.Pool): Promise<void> {
  await migrate(createDatabase(pool), { migrationsFolder: MIGRATIONS_FOLDER });
}
